#define ASRC_ASRDCMD_INTACT_MASK                 (0x800000U)
#define ASRC_ASRDCMD_INTACT_SHIFT                (23U)
#define ASRC_ASRDCMD_INTACT(x)                   (((uint32_t)(((uint32_t)(x)) << ASRC_ASRDCMD_INTACT_SHIFT)) & ASRC_ASRDCMD_INTACT_MASK)
