#define USB3_OTGSTATE_HOST_OTG_STATE_SHIFT       (3U)
/*! HOST_OTG_STATE - Current state of the OTG Host FSM
 *  0b000..H_IDLE
 *  0b001..H_VBUS_ON
 *  0b010..H_VBUS_FAILED
 *  0b011..H_OTG_HOST_MODE
 *  0b100..H_HOST_MODE
 *  0b101..H_SWITCH_TO_DEVICE
 *  0b110..H_A_SUSPEND
 *  0b111..H_WAIT_VBUS_FALL
 */
