#define USBDCD_SIGNAL_OVERRIDE_DMIR(x)           (((uint32_t)(((uint32_t)(x)) << USBDCD_SIGNAL_OVERRIDE_DMIR_SHIFT)) & USBDCD_SIGNAL_OVERRIDE_DMIR_MASK)
